168	async function inspectGit(root: string): Promise<Pick<RepoSnapshot, 'gitBranch' | 'gitStatus'>> {
169	  const gitRoot = await git(root, ['rev-parse', '--show-toplevel']);
170	  if (!gitRoot || path.resolve(gitRoot) !== root) return { gitStatus: [] };
171	
172	  const [gitBranch, status] = await Promise.all([
173	    git(root, ['branch', '--show-current']),
174	    git(root, ['status', '--short', '--no-renames', '--untracked-files=all']),
175	  ]);
