    27	  let parent = root;
    28	  for (const part of parts.slice(0, -1)) {
    29	    parent = path.join(parent, part);
    30	    const info = await lstat(parent);
    31	    if (!info.isDirectory() || info.isSymbolicLink()) {
    32	      throw new RenameFileError('Rename parents must be existing directories without symlinks.');
