    40	  if (input === null || typeof input !== 'object' || Array.isArray(input) ||
    41	    Object.keys(input).sort().join(',') !== 'destination,source' ||
    42	    !('source' in input) || typeof input.source !== 'string' ||
    43	    !('destination' in input) || typeof input.destination !== 'string') {
    44	    throw new RenameFileError('Provide only string source and destination paths.');
    45	  }
