    47	  const destinationParts = relativeParts(input.destination);
    48	  if (input.source === input.destination) throw new RenameFileError('Source and destination must be different.');
    49	
    50	  try {
    51	    const canonicalRoot = await realpath(root);
    52	    if (!(await lstat(canonicalRoot)).isDirectory()) throw new RenameFileError('The selected repository must be a directory.');
    53	    const source = await checkedPath(canonicalRoot, sourceParts);
    54	    const destination = await checkedPath(canonicalRoot, destinationParts);
    55	    const original = await lstat(source);
    56	    if (!original.isFile() || original.isSymbolicLink() || original.nlink !== 1) {
