    21	    throw new RenameFileError('Rename paths must be bounded repository-relative paths without traversal or protected files.');
    22	  }
    23	  return parts;
    24	}
    25	
    26	async function checkedPath(root: string, parts: string[]): Promise<string> {
    27	  let parent = root;
    28	  for (const part of parts.slice(0, -1)) {
    29	    parent = path.join(parent, part);
    30	    const info = await lstat(parent);
    31	    if (!info.isDirectory() || info.isSymbolicLink()) {
    32	      throw new RenameFileError('Rename parents must be existing directories without symlinks.');
    33	    }
    34	  }
    35	  return path.join(root, ...parts);
    36	}
