428	export function proposalSignature(proposal: CandidateProposal, state: AgentState): string {
429	  const semantic = proposal.action === 'CALL_CODEX' || proposal.action === 'CALL_CLAUDE'
430	    ? {
431	      action: proposal.action, evidence: workerEvidenceKey(state),
432	      ...(proposal.action === 'CALL_CODEX' ? { networkAccess: proposal.input.networkAccess === true } : {}),
433	    }
434	    : {
435	      action: proposal.action,
436	      input: proposal.input,
437	      generation: proposal.action === 'RUN_TESTS' ? state.evidence?.validationGeneration ?? 0 : 0,
438	      evidence: proposal.action === 'RUN_TESTS'
439	        ? state.evidence?.clarifications.map((item) => item.text) ?? []
440	        : state.evidence?.revision ?? 0,
441	    };
442	  return createHash('sha256').update(JSON.stringify(semantic)).digest('hex');
443	}

