 93	function configuredSecretValues(): string[] {
 94	  return [...(redactionSecrets.getStore() ?? []),
 95	    ...['AI_GATEWAY_API_KEY', 'OPENROUTER_API_KEY', 'OPENROUTE_API_KEY', 'TYPESAFE_API_KEY', 'TYPESAFE_AI_API_KEY', 'CLOUDFLARE_AUTH_TOKEN']
 96	      .map((name) => process.env[name]?.trim()),
