102	export function evaluationAttribution(evaluation: EvaluationAttribution): EvaluationAttribution {
103	  return {
104	    ...(evaluation.provider === undefined ? {} : { provider: evaluation.provider }),
105	    ...(evaluation.requestedModel === undefined ? {} : { requestedModel: redactSensitiveText(evaluation.requestedModel) }),
106	    ...(evaluation.servedModel === undefined ? {} : { servedModel: redactSensitiveText(evaluation.servedModel) }),
107	  };
