109	
110	export function redactSensitiveText(
111	  value: string,
112	  secretValues: string[] = configuredSecretValues(),
113	): string {
114	  let redacted = value;
115	  for (const secret of secretValues) {
116	    redacted = redacted.replaceAll(secret, REDACTED);
117	  }
118	  return redacted
119	    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
120	    .replace(BEARER_TOKEN, `$1${REDACTED}`);
121	}
122	
123	function takeText(value: string, context: SanitizationContext): string {
124	  const redacted = redactSensitiveText(value, context.secretValues);
125	  const available = Math.min(MAX_TRACE_STRING_LENGTH, context.remainingText);
126	  if (available <= 0) return TRUNCATED;
127	  context.remainingText -= Math.min(redacted.length, available);
128	  return redacted.length > available ? `${redacted.slice(0, available)}${TRUNCATED}` : redacted;
129	}
130	
131	function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
132	  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
133	  if (value === undefined) return '[UNDEFINED]';
134	  if (value === null || typeof value === 'boolean') return value;
135	  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
136	  if (typeof value === 'string') return takeText(value, context);
137	  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
138	    return takeText(String(value), context);
139	  }
140	
141	  if (context.seen.has(value)) return '[CIRCULAR]';
142	  context.seen.add(value);
143	
144	  if (Array.isArray(value)) {
145	    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
146	      .map((item) => sanitizeValue(item, context, depth + 1));
147	    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
148	    return items;
149	  }
150	
151	  if (!isRecord(value)) return takeText(String(value), context);
152	
153	  const entries: { [key: string]: TraceValue } = {};
154	  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
155	  for (const [key, entry] of objectEntries) {
156	    entries[redactSensitiveText(key, context.secretValues)] = SENSITIVE_KEY.test(key)
157	      ? REDACTED
158	      : sanitizeValue(entry, context, depth + 1);
159	  }
160	  if (Object.keys(value).length > MAX_TRACE_OBJECT_ENTRIES) entries.truncated = TRUNCATED;
161	  return entries;
162	}
163	
164	export function sanitizeTraceValue(
165	  value: unknown,
166	  secretValues: string[] = configuredSecretValues(),
167	): TraceValue {
168	  const sanitized = sanitizeValue(value, {
169	    remainingText: MAX_TRACE_TEXT_BUDGET,
170	    seen: new WeakSet<object>(),
171	    secretValues,
172	  }, 0);
173	  const serialized = JSON.stringify(sanitized);
174	  if (Buffer.byteLength(serialized, 'utf8') <= MAX_TRACE_VALUE_BYTES) return sanitized;
175	
176	  return {
177	    truncated: true,
178	    preview: takeText(serialized, {
179	      remainingText: Math.floor(MAX_TRACE_VALUE_BYTES / 4),
180	      seen: new WeakSet<object>(),
181	      secretValues,
182	    }),
183	  };
184	}
