236	export async function writeTrace(
237	  root: string,
238	  payload: {
239	    state: AgentState;
240	    evaluation: EvaluationResult;
241	    policy: PolicyDecision;
242	  },
243	): Promise<string> {
244	  try {
245	    const trace = await uniqueTracePath(root);
246	    const record = makeTraceRecord(payload, new Date(), trace.runId);
247	    await writeFile(trace.path, `${JSON.stringify(record)}\n`);
248	    return trace.path;
249	  } catch {
250	    throw new TraceWriteError();
251	  }
252	}
