 366	async function safelyExecute(
 367	  proposal: Exclude<CandidateProposal, { action: 'ASK_USER' | 'FINISH' }>,
 368	  execute: typeof executeCandidate,
 369	  options: ExecutionOptions,
 370	): Promise<ToolResult> {
 371	  const startedAt = performance.now();
 372	  try {
 373	    const result: unknown = await (options.signal ? execute(proposal, undefined, options) : execute(proposal));
 374	    if (!isToolResult(result, proposal)) {
 375	      throw new Error('The tool executor returned a malformed result.');
 376	    }
 377	    return options.signal?.aborted
 378	      ? { ...result, ok: false, cancelled: true }
 379	      : result;
 380	  } catch (error) {
 381	    return {
 382	      action: proposal.action,
 383	      ok: false,
 384	      exitCode: null,
 385	      durationMs: Math.round(performance.now() - startedAt),
 386	      timedOut: false,
 387	      ...(options.signal?.aborted ? { cancelled: true } : {}),
 388	      output: truncateText(
 389	        options.signal?.aborted ? 'Tool execution interrupted.' : error instanceof Error ? error.message : 'Tool execution failed.',
 390	        MAX_OBSERVATION_LENGTH,
 391	      ),
 392	      files: [],
 393	    };
 394	  }
 395	}
