396	export function parseApprovalChoice(
397	  value: string,
398	  context: ApprovalContext,
399	): ApprovalDecision | undefined {
400	  const normalized = value.trim().toUpperCase();
401	  if (normalized === 'A' || normalized === 'APPROVE') return { kind: 'approve' };
402	  if (normalized === 'R' || normalized === 'REJECT') return { kind: 'reject' };
403	  if (normalized === 'STOP' || normalized === 'QUIT') return { kind: 'stop' };
404	
405	  const actionAliases: Partial<Record<string, ApprovalDecision>> = {
406	    SEARCH: { kind: 'alternative', action: 'SEARCH_REPO' },
407	    SEARCH_REPO: { kind: 'alternative', action: 'SEARCH_REPO' },
408	    READ: { kind: 'alternative', action: 'READ_FILE' },
409	    READ_FILE: { kind: 'alternative', action: 'READ_FILE' },
410	    ISSUE: { kind: 'alternative', action: 'READ_ISSUE' },
411	    READ_ISSUE: { kind: 'alternative', action: 'READ_ISSUE' },
412	    COMMAND: { kind: 'alternative', action: 'RUN_COMMAND' },
413	    RUN_COMMAND: { kind: 'alternative', action: 'RUN_COMMAND' },
414	    TEST: { kind: 'alternative', action: 'RUN_TESTS' },
415	    RUN_TESTS: { kind: 'alternative', action: 'RUN_TESTS' },
416	    CODEX: { kind: 'alternative', action: 'CALL_CODEX' },
417	    CALL_CODEX: { kind: 'alternative', action: 'CALL_CODEX' },
418	    CLAUDE: { kind: 'alternative', action: 'CALL_CLAUDE' },
419	    CALL_CLAUDE: { kind: 'alternative', action: 'CALL_CLAUDE' },
420	    ASK: { kind: 'alternative', action: 'ASK_USER' },
421	    ASK_USER: { kind: 'alternative', action: 'ASK_USER' },
422	    FINISH: { kind: 'alternative', action: 'FINISH' },
423	  };
424	  const decision = actionAliases[normalized];
425	  if (decision?.kind === 'alternative' && context.allowedAlternatives.includes(decision.action)) {
426	    return decision;
427	  }
428	  return undefined;
429	}
