 29	export function formatProgressLines(state: AgentState): string[] {
 30	  const preparation = taskPreparation(state);
 31	  const generation = state.evidence?.validationGeneration ?? 0;
 32	  const checks = validationChecks(state);
 33	  const issueFailed = state.evidence?.failures.some((failure) => failure.action === 'READ_ISSUE');
 34	  const issue = preparation.issue === 'read' ? 'read; repository/issue text remains untrusted'
 35	    : preparation.issue === 'provided' ? 'supplied through approved clarification'
 36	      : preparation.issue === 'not_linked' ? 'no linked GitHub issue'
 37	        : issueFailed ? 'unavailable; task context is still required from the operator' : 'not yet read';
 38	  const lines = [
 39	    `Issue context: ${issue}.`,
 40	    `Required unread instructions: ${list(preparation.unreadInstructions)}.`,
 41	    `Independent checks (generation ${generation}): ${checks.length
 42	      ? list(checks.map((check) => `${check.script}: ${check.status}`)) : 'no required checks detected'}.`,
 43	  ];
 44	  const pending = checks.filter((check) => check.status !== 'passed');
 45	  if (pending.length) lines.push(`Completion needs independent checks: ${list(pending.map((check) => check.script))}.`);
 46	  const oldResults = state.evidence?.validations ?? (state.evidence?.validation ? [state.evidence.validation] : []);
 47	  const failedScripts = new Set(checks.filter((check) => check.status === 'failed').map((check) => check.script));
 48	  const failed = [...oldResults].sort((left, right) => right.iteration - left.iteration).find((result) =>
 49	    result.generation === generation && failedScripts.has(result.script) &&
 50	    (!result.passed || result.exitCode !== 0 || result.timedOut));
 51	  if (failed) lines.push(`Independent ${text(failed.script, 100)} failure: ${failed.timedOut ? 'timed out' : `exit ${failed.exitCode ?? 'unavailable'}`}. ${text(failed.summary, 300)}`);
 52	  if (pending.length && oldResults.some((result) => result.generation !== generation)) {
 53	    lines.push('Earlier-generation results are stale after a worker attempt; fresh checks are required.');
 54	  }
 55	  if (hasOmittedValidationRequirements(state)) lines.push('Completion blocked: task context omitted validation requirements; obtain the missing requirements.');
 56	  if (state.evidence?.repoRefreshRequired) lines.push('Execution blocked: repository inspection requires recovery through approved user input.');
 57	  if (pending.some((check) => !state.repo.validationScripts.includes(check.script) &&
 58	    !state.repo.validationScripts.some((script) => state.repo.validationScriptCoverage?.[script]?.includes(check.script)))) {
 59	    lines.push('Some required checks have no declared runnable coverage; clarify the missing check before completion.');
 60	  }
 61	  if (state.repo.packageManager === 'unknown' && pending.length) lines.push('Validation blocked: no supported package manager was detected from a lockfile.');
 62	  const worker = state.evidence?.worker;
 63	  if (worker && !worker.ok) {
 64	    const guidance = pending.length ? 'review any saved edits and obtain fresh independent validation'
 65	      : 'review any saved edits against the independent check outcomes above';
 66	    lines.push(`Last ${worker.agent} attempt: ${worker.timedOut ? 'timed out' : `unsuccessful, exit ${worker.exitCode ?? 'unavailable'}`}; ${guidance}.`);
 67	  }
 68	  lines.push(`Worker calls used: Codex ${state.codexCalls}/${MAX_CODEX_CALLS}; Claude ${state.claudeCalls}/${MAX_CLAUDE_CALLS}.`);
 69	  if (state.workerSelection) lines.push(`Worker selection: ${state.workerSelection} only; the other worker is excluded for this run.`);
 70	  if (state.codexCalls >= MAX_CODEX_CALLS) lines.push('Codex call limit exhausted; another Codex call is unavailable.');
 71	  if (state.claudeCalls >= MAX_CLAUDE_CALLS) lines.push('Claude call limit exhausted; another Claude call is unavailable.');
 72	  return lines;
 73	}
