137	export function formatOutcomeLines(result: OrchestrationResult): string[] {
138	  const lines: string[] = [];
139	  if (result.status === 'finished') {
140	    lines.push('Task acceptance: approved after independent validation.');
141	  } else if (result.status === 'iteration_limit') {
142	    lines.push(`Iteration budget exhausted after ${result.iterations} iterations; task completion was not approved.`);
143	    if (result.summary.validation.passed) lines.push('All required independent checks passed, but acceptance review did not complete within the budget.');
144	  } else if (result.status === 'evaluation_failed') {
145	    lines.push('Evaluation stopped this run; no action was approved from the failed evaluation.');
146	  } else {
