148	      ? 'A signal interrupted this run; partial edits and evidence were preserved.'
149	      : 'Run stopped without claiming task completion; edits and evidence were preserved.');
150	  }
151	  if (result.status !== 'finished') {
152	    lines.push(...formatProgressLines(result.state));
153	    if (hasPassedValidation(result.state)) lines.push('Passing validation is supporting evidence; the task outcome still needs acceptance review.');
