 33	export async function createClaudeToolHandler(root: string): Promise<(message: unknown) => Promise<ToolResponse | undefined>> {
 34	  const canonicalRoot = await realpath(root);
 35	  if (!(await stat(canonicalRoot)).isDirectory()) throw new Error('The repository must be a directory.');
 36	  let phase: 'new' | 'initializing' | 'ready' = 'new';
 37	  let renameAttempts = 0;
 38	
 39	  return async (message) => {
 40	    if (!isRecord(message) || message.jsonrpc !== '2.0' || typeof message.method !== 'string') {
 41	      return failure(null, -32600, 'Invalid request.');
 42	    }
 43	    if (message.id === undefined) {
 44	      if (message.method === 'notifications/initialized' && phase === 'initializing') phase = 'ready';
 45	      return undefined; // Notifications cannot execute tools.
 46	    }
 47	    if (!(typeof message.id === 'string' && message.id.length <= 100) &&
 48	      !(typeof message.id === 'number' && Number.isSafeInteger(message.id))) {
 49	      return failure(null, -32600, 'Invalid request id.');
 50	    }
 51	    const id = message.id;
 52	    const params = isRecord(message.params) ? message.params : {};
 53	    if (message.method === 'ping') return { jsonrpc: '2.0', id, result: {} };
 54	    if (message.method === 'initialize') {
 55	      if (phase !== 'new') return failure(id, -32600, 'Already initialized.');
 56	      if (typeof params.protocolVersion !== 'string') return failure(id, -32602, 'Missing protocol version.');
 57	      phase = 'initializing';
 58	      return { jsonrpc: '2.0', id, result: {
 59	        protocolVersion: PROTOCOL_VERSIONS.includes(params.protocolVersion) ? params.protocolVersion : '2025-11-25',
 60	        capabilities: { tools: {} },
 61	        serverInfo: { name: 'jev-files', version: '1.0.0' },
 62	      } };
 63	    }
 64	    if (message.method !== 'tools/list' && message.method !== 'tools/call') return failure(id, -32601, 'Unknown method.');
 65	    if (phase !== 'ready') return failure(id, -32002, 'Initialize the tool connection first.');
 66	    if (message.method === 'tools/list') {
 67	      return { jsonrpc: '2.0', id, result: { tools: [{
 68	        name: 'rename_file',
 69	        description: 'Rename one regular file within the approved repository. Supply source and destination paths relative to the repository. Existing destinations, symlinks, protected paths, directories and files over 1 MiB are refused. Use this instead of copying a file to simulate a rename.',
 70	        inputSchema: {
 71	          type: 'object',
 72	          properties: {
 73	            source: { type: 'string', minLength: 1, maxLength: MAX_RENAME_PATH_LENGTH },
 74	            destination: { type: 'string', minLength: 1, maxLength: MAX_RENAME_PATH_LENGTH },
 75	          },
 76	          required: ['source', 'destination'],
 77	          additionalProperties: false,
 78	        },
 79	        annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: false },
 80	      }] } };
 81	    }
 82	    if (params.name !== 'rename_file') return failure(id, -32602, 'Unknown tool.');
 83	    if (renameAttempts >= MAX_CLAUDE_RENAMES) return toolResult(id, 'The rename-attempt limit has been reached.', true);
 84	    renameAttempts += 1;
 85	    try {
 86	      const renamed = await renameRepositoryFile(canonicalRoot, params.arguments);
 87	      return toolResult(id, JSON.stringify(renamed), false);
 88	    } catch (error) {
 89	      return toolResult(id, error instanceof RenameFileError ? error.message : 'The rename failed.', true);
 90	    }
 91	  };
 92	}
