 94	/** A private stdio MCP endpoint: no listener, shell, file contents, or other tools. */
 95	export async function serveClaudeTools(root: string, input: Readable, output: Writable): Promise<void> {
 96	  const handle = await createClaudeToolHandler(root);
 97	  let pending = Buffer.alloc(0);
 98	  let messages = 0;
 99	  for await (const chunk of input) {
100	    pending = Buffer.concat([pending, Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk))]);
101	    let newline: number;
102	    while ((newline = pending.indexOf(10)) !== -1) {
103	      if (newline > MAX_TOOL_MESSAGE_BYTES) throw new Error('Tool message size limit exceeded.');
104	      const frame = pending.subarray(0, newline).toString('utf8');
105	      pending = pending.subarray(newline + 1);
106	      if (frame.trim() === '') continue;
107	      messages += 1;
108	      if (messages > MAX_TOOL_MESSAGES) throw new Error('Tool message limit exceeded.');
109	      let response: ToolResponse | undefined;
110	      try {
111	        const message: unknown = JSON.parse(frame);
112	        response = await handle(message);
113	      } catch {
114	        response = failure(null, -32700, 'Invalid JSON.');
115	      }
116	      if (response && !output.write(`${JSON.stringify(response)}\n`)) await once(output, 'drain');
117	    }
118	    if (pending.length > MAX_TOOL_MESSAGE_BYTES) throw new Error('Tool message size limit exceeded.');
119	  }
120	  if (pending.length !== 0) throw new Error('Incomplete tool message.');
121	}
122	
123	const entry = process.argv[1];
124	if (entry !== undefined && import.meta.url === pathToFileURL(path.resolve(entry)).href) {
125	  const root = process.argv[2];
126	  if (!root || process.argv.length !== 3) {
127	    process.stderr.write('The rename tool requires one approved repository root.\n');
128	    process.exitCode = 1;
129	  } else {
130	    void serveClaudeTools(root, process.stdin, process.stdout).catch(() => {
131	      process.stderr.write('The rename tool stopped after invalid input or a filesystem error.\n');
132	      process.exitCode = 1;
133	    });
134	  }
135	}

