 10	const MAX_TOOL_MESSAGES = 64;
 11	const PROTOCOL_VERSIONS = ['2024-11-05', '2025-03-26', '2025-06-18', '2025-11-25'];
 12	
 13	type JsonRpcId = string | number | null;
 14	type ToolResponse = {
 15	  jsonrpc: '2.0';
 16	  id: JsonRpcId;
 17	  result?: Record<string, unknown>;
 18	  error?: { code: number; message: string };
 19	};
