 21	function isRecord(value: unknown): value is Record<string, unknown> {
 22	  return value !== null && typeof value === 'object' && !Array.isArray(value);
 23	}
 24	
 25	function failure(id: JsonRpcId, code: number, message: string): ToolResponse {
 26	  return { jsonrpc: '2.0', id, error: { code, message } };
 27	}
 28	
 29	function toolResult(id: JsonRpcId, text: string, isError: boolean): ToolResponse {
 30	  return { jsonrpc: '2.0', id, result: { content: [{ type: 'text', text }], isError } };
 31	}
