  3	export const VALIDATION_NAMES = ['verify', 'check', 'test', 'typecheck', 'lint', 'build'] as const;
  4	
  5	export function isValidationScript(script: string): boolean {
  6	  return /^[a-zA-Z0-9][a-zA-Z0-9:_-]{0,199}$/u.test(script) &&
  7	    VALIDATION_NAMES.some((name) => script === name || script.startsWith(`${name}:`));
  8	}
